package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class WorldProcedure079Test {
 static JSONObject waitDone(WorldProcedure079 runner,String id)throws Exception{for(int i=0;i<24000;i++){var j=runner.read(id);if(!j.getString("status").equals("running"))return j;Thread.sleep(10);}throw new AssertionError("Procedure timed out");}
 static JSONObject args(JSONObject s,String mode){return new JSONObject().put("targets",s.getJSONArray("targets")).put("forceLimitN",s.getDouble("forceLimitN")).put("torqueLimitNm",s.getDouble("torqueLimitNm")).put("memoryMode079",mode);}
 @Test public void actualProcedureCommitsOnceReusesCurrentWorldAndRejectsChangedEvidence()throws Exception {
  var root=Files.createTempDirectory("world079-native-");System.out.println("WORLD079_NATIVE "+root);var s=Procedure079Test.protocol().getJSONArray("training").getJSONObject(0);var ledger=new WorldLedger(root);var world=ledger.create(SpatialScene.parse(s.getJSONObject("source").toString(),UUID.randomUUID().toString()),"Actual079unit");String id=UUID.randomUUID().toString();var binding=WorldLedger.binding(world);JSONObject settled;
  try(var runner=new WorldProcedure079(root,ledger)){runner.start(id,binding,args(s,"simple"));settled=waitDone(runner,id);assertEquals(settled.optString("reason"),"ready",settled.getString("status"));assertTrue(runner.audit(id).getBoolean("passed"));var packed=runner.export(id).getJSONArray("originals").getJSONObject(0);try(var gz=new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(Base64.getDecoder().decode(packed.getString("gzipBase64"))))){var forecast=new JSONObject(new String(gz.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));var actualAttempt=settled.getJSONObject("arm").getJSONArray("attempts").getJSONObject(1);RebuildCompatibility079Test.freshNativeProof(forecast,runner.last(id),actualAttempt);}var report=WorldLedgerTest.meta();var receipt=WorldLedgerTest.receipt(runner.last(id));var commit=ledger.commitProcedure079(runner,id,receipt,report);assertTrue(commit.similar(ledger.commitProcedure079(runner,id,receipt,report)));assertEquals(1,ledger.observe(world.getString("id")).getInt("expectedRevision"));assertThrows(Exception.class,()->runner.start(UUID.randomUUID().toString(),binding,args(s,"adaptive")));var memory=runner.retain(id,commit);assertEquals(1,runner.bank().length());assertEquals("direct",memory.getString("family"));
   var changed=WorldFrames.copy(s);for(Object x:changed.getJSONArray("targets")){var t=(JSONObject)x;t.getJSONArray("positionM").put(0,t.getJSONArray("positionM").getDouble(0)-.1);}String next=UUID.randomUUID().toString();runner.start(next,WorldLedger.binding(ledger.read(world.getString("id"))),args(changed,"memory"));var j=waitDone(runner,next);assertEquals(j.optString("reason"),"ready",j.getString("status"));assertEquals("hit",j.getJSONObject("lookupProof").getString("mode"));assertTrue(j.getJSONObject("initialFrame").similar(commit.getJSONObject("frame")));var two=ledger.commitProcedure079(runner,next,WorldLedgerTest.receipt(runner.last(next)),WorldLedgerTest.meta());assertEquals(2,two.getInt("revision"));assertTrue(two.getJSONObject("frame").getLong("elapsedTicks")>commit.getJSONObject("frame").getLong("elapsedTicks"));try(var nativeStore=new WorldNativeStore(root)){assertEquals(2,WorldExport079.pack(ledger.read(world.getString("id")),nativeStore,runner).getJSONArray("procedures").length());}
   var bad=WorldFrames.copy(j);bad.getJSONObject("decision").getJSONObject("candidate").put("lowerSavingMillis",999999);assertThrows(Exception.class,()->runner.audit(bad));var attempt=settled.getJSONObject("arm").getJSONArray("attempts").getJSONObject(0);var path=root.resolve("world-procedures-079").resolve(id).resolve("attempts").resolve(attempt.getString("id")).resolve("original.json");var original=Files.readString(path);Files.writeString(path,original.replaceFirst("\"goalId\":\"","\"goalId\":\"changed-"));assertThrows(Exception.class,()->runner.audit(id));Files.writeString(path,original);
  }
  try(var cold=new WorldProcedure079(root,new WorldLedger(root))){assertEquals(1,cold.bank().length());assertTrue(cold.audit(id).getBoolean("passed"));
   var changed=WorldFrames.copy(s);for(Object x:changed.getJSONArray("targets")){var t=(JSONObject)x;t.getJSONArray("positionM").put(0,t.getJSONArray("positionM").getDouble(0)-.2);}String next=UUID.randomUUID().toString();cold.start(next,WorldLedger.binding(ledger.read(world.getString("id"))),args(changed,"memory"));var j=waitDone(cold,next);assertEquals(j.optString("reason"),"ready",j.getString("status"));assertEquals("full",j.getJSONObject("lookupProof").getString("mode"));assertFalse(j.getJSONObject("decision").getJSONObject("candidate").getBoolean("warm"));assertTrue(cold.audit(next).getBoolean("passed"));
  }
 }
}
